void process_hid_input(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    int j;
    int k;
    int *values;
    int index = 0;
    int new_value;

    if (!(values = kmalloc(field->report_count * sizeof(int), GFP_ATOMIC))) {
        return;
    }

    for (i = 0; i < field->report_count; i++) {
        new_value = 0;
        for (j = 0; j < field->maxusage; j++) {
            if (field->logical_min < field->logical_max) {
                int value = hid->ll_driver->report_raw(field->hidinput, field->usage + j, data + field->report_offset + i * field->report_size, field->report_size, interrupt);
                if (value < field->logical_min)
                    value = field->logical_min;
                if (value > field->logical_max)
                    value = field->logical_max;
                new_value += value;
            } else {
                new_value = field->logical_max;
            }
        }

        if (field->flags & HID_MAIN_ITEM_CONSTANT)
            new_value = 0;

        if (field->flags & HID_MAIN_ITEM_RELATIVE)
            new_value = 0;

        values[index++] = new_value;
    }

    for (k = 0; k < field->report_count; k++) {
        hid_process_event(hid, field->hidinput, field->usage + k, values[k]);
    }

    for (i = 0; i < field->report_count; i++) {
        field->value[i] = values[i];
    }

    kfree(values);
}

void hid_handle_input_event(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i, j;
    int *values;
    struct hid_report *report;

    values = kmalloc(field->report_count * sizeof(int), GFP_ATOMIC);
    if (!values)
        return;

    for (i = 0; i < field->report_count; i++) {
        values[i] = hid_field_value(field, data, i);
        if (values[i] < field->logical_minimum || values[i] > field->logical_maximum)
            continue;

        for (j = 0; j < field->maxusage; j++) {
            if (field->usage[j].usage != HID_UP_UNDEFINED) {
                hid_process_event(hid, field->report_id, field->usage[j].usage, values[i], interrupt);
            }
        }
    }

    for (i = 0; i < field->report_count; i++) {
        field->value[i] = values[i];
    }

    kfree(values);
}

