void process_hid_input(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    int j;
    int *values;
    int new;

    values = kmalloc(field->report_count * sizeof(int), GFP_KERNEL);
    if (!values)
        return;

    for (i = 0; i < field->report_count; i++) {
        values[i] = hid->driver->report->hidinput_input_get_value(field, i);
        new = hid->driver->report->hidinput_input_get_value(field, i);
        if (new != values[i]) {
            hid_process_event(hid, field, i, new);
            values[i] = new;
        }
    }

    for (j = 0; j < field->maxusage; j++)
        field->value[j] = values[j];

    kfree(values);
}

void process_hid_input(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    int j;
    int *values;
    int allocated = 0;

    if (!field->maxfield) return;

    values = kmalloc(field->maxfield * sizeof(int), GFP_ATOMIC);
    if (!values) return;
    allocated = 1;

    for (i = 0; i < field->report_count; i++) {
        for (j = 0; j < field->maxfield; j++) {
            struct hid_usage *usage = &field->usage[i * field->maxusage + j];
            __s32 value = hid_input_data(hid, usage, data + field->report_offset, field->report_size, i, interrupt);
            if (value < usage->value)
                hid->status &= ~HID_STAT_ADDED;
            if (value != usage->value) {
                usage->value = value;
                hid_process_event(hid, usage->hid, usage->type, usage->number, value);
            }
        }
    }

    for (i = 0; i < field->maxfield; i++)
        field->value[i] = values[i];

    if (allocated)
        kfree(values);
}
